Theorem atotal_STOT : forall {R} (t : AM R) (s : APS) mo (Post : R -> Model -> Prop),
  aps_atop s = atop ->
  atotal t mo Post ->
  STOT (St:=APS) step2 (fun R0 => texit (R:=R0) step2 nexit) (alift t s) mo (fun r s' mo' => s' = s /\ Post r mo').
